def main():
    here = os.path.dirname(os.path.abspath(__file__))
    corpus_dir = os.path.join(here, "corpus")
    os.makedirs(corpus_dir, exist_ok=True)
    out = os.path.join(corpus_dir, "news_fallback.json")
    data = {"module": "news_fallback", "keep_days": 14, "rounds": len(CARDS), "items": CARDS}
    with open(out, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print("written %s  rounds=%d cards/round=%d total=%d"
          % (out, len(CARDS), len(CARDS[0]), sum(len(r) for r in CARDS)))

if __name__ == "__main__":
    main()
